// src/theme/index.ts
import { getThemeInitScript } from "@starwind-ui/runtime/theme";
import * as React from "react";
import { getThemeInitScript as getThemeInitScript2, initThemeController } from "@starwind-ui/runtime/theme";
function ThemeInitScript(options = {}) {
  return React.createElement("script", {
    "data-starwind-theme-init": "",
    dangerouslySetInnerHTML: { __html: getThemeInitScript(options) }
  });
}

export {
  ThemeInitScript,
  getThemeInitScript2 as getThemeInitScript,
  initThemeController
};
